mapper.delete:
DELETE FROM idempotency_record
WHERE operator_id = #{operatorId}
  AND operation_type = #{operationType}
  AND idempotency_key = #{idempotencyKey}
  AND expires_at <= #{now}

mapper.select:
SELECT id, operator_id, operation_type, idempotency_key, request_hash, status,
       resource_type, resource_id, response_code, failure_message, locked_until,
       created_at, updated_at, expires_at
FROM idempotency_record
WHERE operator_id = #{operatorId}
  AND operation_type = #{operationType}
  AND idempotency_key = #{idempotencyKey}
FOR UPDATE

mapper.update:
UPDATE idempotency_record
SET status = 'PROCESSING', locked_until = #{lockedUntil}, response_code = NULL,
    failure_message = NULL, updated_at = #{updatedAt}
WHERE id = #{id}
  AND status IN ('PROCESSING', 'FAILED_RETRYABLE')

UPDATE idempotency_record
SET status = 'SUCCEEDED', resource_type = #{resourceType}, resource_id = #{resourceId},
    response_code = 'SUCCESS', failure_message = NULL, locked_until = NULL,
    updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING' AND locked_until = #{expectedLockedUntil}

UPDATE idempotency_record
SET status = #{status}, response_code = #{responseCode}, failure_message = #{failureMessage},
    locked_until = NULL, updated_at = #{updatedAt}
WHERE id = #{id} AND status = 'PROCESSING' AND locked_until = #{expectedLockedUntil}
